// ── EDIT THIS CONFIG ONCE ─────────────────────────────────
const CONFIG = {
  fromEmail: 'hello@mediportbd.com',
  storeName: 'MediportBD',
  storeUrl: 'https://mediportbd.com',
  welcomeCoupon: 'WELCOME10'
};
// ──────────────────────────────────────────────────────────
const d = ($input.item.json.body && $input.item.json.body.data !== undefined ? $input.item.json.body.data : $input.item.json.data) || {};
const isB2B = d.role === 'b2b_customer';
const html = `
  <div style="font-family:Arial,sans-serif;max-width:560px;margin:auto">
    <h2>Welcome to ${CONFIG.storeName}, ${d.name}! 🎉</h2>
    <p>Thanks for creating your account${isB2B ? ' as a B2B partner' : ''}. Here is what you can do next:</p>
    <ul>
      <li>Browse ${isB2B ? 'wholesale-priced' : 'authentic'} medical equipment</li>
      <li>Track orders and reorders in one place</li>
      <li>Earn loyalty points on every purchase</li>
    </ul>
    ${isB2B ? '<p>As a B2B customer you can request instant quotations with NET terms directly from any product page.</p>' : `<p>Start with <b>${CONFIG.welcomeCoupon}</b> for 10% off your first order:</p>`}
    <p><a href="${CONFIG.storeUrl}" style="background:#0d6efd;color:#fff;padding:12px 28px;text-decoration:none;border-radius:6px;display:inline-block">Shop Now</a></p>
  </div>`;
return { json: { CONFIG, email: d.email, name: d.name, subject: `Welcome to ${CONFIG.storeName}${isB2B ? ' — B2B account activated' : ' 🎉'}`, html } };

